async function readForm(request) {
  const chunks = [];
  let bodySize = 0;
  for await (const chunk of request) {
    bodySize += chunk.length;
    if (bodySize > 1_048_576) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    const search = (url.searchParams.get('search') ?? '').trim();
    const projectFilter = url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active';
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      html(response, 200, projectsPage('', projectFilter, search));
    } else if ((request.method === 'GET' && url.pathname === '/directory') ||
      (request.method === 'POST' && ['/directory/due-range', '/directory/complete', '/directory/reopen'].includes(url.pathname))) {
      const scope = url.searchParams.get('scope') === 'Archived' ? 'Archived' : 'Active';
      const requestedFilter = url.searchParams.get('filter');
      const filter = ['Open', 'Completed', 'Deleted'].includes(requestedFilter) ? requestedFilter : 'All';
      const requestedPriority = url.searchParams.get('priorityFilter');
      const priorityFilter = taskPriorities.includes(requestedPriority) ? requestedPriority : 'All';
      const dueRange = {
        from: (url.searchParams.get('dueFrom') ?? '').trim(),
        through: (url.searchParams.get('dueThrough') ?? '').trim(),
      };
      const rangeError = dueRangeError(dueRange);
      if (rangeError) {
        html(response, 400, directoryPage(scope, filter, priorityFilter, { from: '', through: '' }, search, rangeError));
        return;
      }
      if (request.method === 'GET') {
        html(response, 200, directoryPage(scope, filter, priorityFilter, dueRange, search));
      } else if (url.pathname !== '/directory/due-range') {
        setDirectoryCompletion(scope, filter, priorityFilter, dueRange, search, url.pathname === '/directory/complete');
        redirect(response, `/directory?${directoryQuery(scope, filter, priorityFilter, dueRange, search)}`);
      } else {
        const body = await readForm(request);
        const nextRange = {
          from: (body.get('dueFrom') ?? '').trim(),
          through: (body.get('dueThrough') ?? '').trim(),
        };
        const error = dueRangeError(nextRange);
        if (error) {
          html(response, 400, directoryPage(scope, filter, priorityFilter, dueRange, search, error));
        } else {
          redirect(response, `/directory?${directoryQuery(scope, filter, priorityFilter, nextRange, search)}`);
        }
      }
    } else if (request.method === 'POST' && url.pathname === '/projects/import') {
      const body = await readForm(request);
      const fields = { json: body.get('json') ?? '', name: body.get('name') ?? '' };
      const name = fields.name.trim();
      const project = parseProjectDocument(fields.json);
      if (!name || !project) {
        html(response, 400, projectsPage(!name ? 'Project name is required' : 'Invalid project JSON',
          projectFilter, search, fields));
        return;
      }
      const id = importProject(name, project);
      redirect(response, `/projects/${id}`);
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const body = await readForm(request);
      const name = (body.get('name') ?? '').trim();
      if (!name) {
        html(response, 400, projectsPage('Project name is required', projectFilter, search));
        return;
      }
      createProject.run(name);
      redirect(response, search ? `/?${projectListQuery(projectFilter, search)}` : '/');
    } else if (request.method === 'POST' && /^\/projects\/\d+\/(archive|restore)$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      if (!Number.isSafeInteger(id) || !setProjectArchived.run(url.pathname.endsWith('/archive') ? 1 : 0, id).changes) {
        html(response, 404, page('Project not found', '<h1>Project not found</h1>'));
        return;
      }
      redirect(response, search ? `/?${projectListQuery(projectFilter, search)}` : (url.pathname.endsWith('/restore') ? '/?filter=Archived' : '/'));
    } else if ((request.method === 'GET' && /^\/projects\/\d+(?:\/export)?$/.test(url.pathname)) ||
      (request.method === 'POST' && /^\/projects\/\d+\/(?:rename|default-task-priority|due-range|tasks(?:\/\d+(?:\/(?:rename|priority|due-date|notes|move|delete|restore))?)?)$/.test(url.pathname))) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? getProject.get(id) : undefined;
      if (!project) {
        html(response, 404, page('Project not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      if (request.method === 'GET' && url.pathname.endsWith('/export')) {
        downloadProject(response, project);
        return;
      }
      const requestedFilter = url.searchParams.get('filter');
      const filter = ['Open', 'Completed', 'Deleted'].includes(requestedFilter) ? requestedFilter : 'All';
      const requestedPriorityFilter = url.searchParams.get('priorityFilter');
      const priorityFilter = taskPriorities.includes(requestedPriorityFilter) ? requestedPriorityFilter : 'All';
      const dueRange = {
        from: (url.searchParams.get('dueFrom') ?? '').trim(),
        through: (url.searchParams.get('dueThrough') ?? '').trim(),
      };
      // Query parameters carry only the applied range between page requests.
      const rangeError = dueRangeError(dueRange);
      if (rangeError) {
        html(response, 400, page('Invalid due range', `<p role="alert">${rangeError}</p>`));
        return;
      }
      if (request.method === 'GET') {
        html(response, 200, projectPage(project, filter, '', priorityFilter, dueRange, search));
      } else {
        const body = await readForm(request);
        const currentProject = getProject.get(project.id);
        if (url.pathname.endsWith('/due-range')) {
          const nextRange = {
            from: (body.get('dueFrom') ?? '').trim(),
            through: (body.get('dueThrough') ?? '').trim(),
          };
          const error = dueRangeError(nextRange);
          if (error) {
            html(response, 400, projectPage(currentProject, filter, error, priorityFilter, dueRange, search));
          } else {
            redirect(response, `/projects/${project.id}?${taskFilterQuery(filter, priorityFilter, nextRange, search)}`);
          }
          return;
        }
        if (currentProject.archived) {
          html(response, 403, projectPage(currentProject, filter, 'Archived project', priorityFilter, dueRange, search));
          return;
        }
        const taskId = url.pathname.split('/')[4];
        if (taskId !== undefined) {
          const task = getOwnedTask.get(Number(taskId), project.id);
          if (!task) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
          if (task.deleted && !url.pathname.endsWith('/restore')) {
            html(response, 403, projectPage(currentProject, filter, 'Deleted task must be restored before editing', priorityFilter, dueRange, search));
            return;
          }
        }
        if (taskId !== undefined && (url.pathname.endsWith('/delete') || url.pathname.endsWith('/restore'))) {
          setTaskDeleted.run(url.pathname.endsWith('/delete') ? 1 : 0, Number(taskId), project.id);
        } else if (url.pathname.endsWith('/default-task-priority')) {
          const priority = body.get('priority');
          if (!taskPriorities.includes(priority)) {
            html(response, 400, projectPage(currentProject, filter, 'Invalid task priority', priorityFilter, dueRange, search));
            return;
          }
          setDefaultTaskPriority.run(priority, project.id);
        } else if (url.pathname.endsWith('/rename') && taskId === undefined) {
          const name = (body.get('name') ?? '').trim();
          if (!name) {
            html(response, 400, projectPage(currentProject, filter, 'Project name is required', priorityFilter, dueRange, search));
            return;
          }
          renameProject.run(name, project.id);
        } else if (taskId === undefined) {
          const title = (body.get('title') ?? '').trim();
          if (!title) {
            html(response, 400, projectPage(project, filter, 'Task title is required', priorityFilter, dueRange, search));
            return;
          }
          createTask(project.id, title, currentProject.default_task_priority);
        } else if (url.pathname.endsWith('/move')) {
          const destinationId = Number(body.get('destinationProject'));
          const destination = Number.isSafeInteger(destinationId) ? getProject.get(destinationId) : undefined;
          if (!destination || destination.archived || destination.id === project.id) {
            html(response, 400, projectPage(currentProject, filter, 'Choose an active destination project', priorityFilter, dueRange, search));
            return;
          }
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !moveTask(id, project.id, destination.id)) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        } else if (url.pathname.endsWith('/rename')) {
          const title = (body.get('title') ?? '').trim();
          if (!title) {
            html(response, 400, projectPage(currentProject, filter, 'Task title is required', priorityFilter, dueRange, search));
            return;
          }
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !renameTask.run(title, id, project.id).changes) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        } else if (url.pathname.endsWith('/due-date')) {
          const dueDate = (body.get('dueDate') ?? '').trim();
          if (!isValidDueDate(dueDate)) {
            html(response, 400, projectPage(currentProject, filter, 'Due date must be a valid YYYY-MM-DD date', priorityFilter, dueRange, search));
            return;
          }
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !setTaskDueDate.run(dueDate, id, project.id).changes) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        } else if (url.pathname.endsWith('/notes')) {
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !setTaskNotes.run(body.get('notes') ?? '', id, project.id).changes) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        } else if (url.pathname.endsWith('/priority')) {
          const priority = body.get('priority');
          if (!taskPriorities.includes(priority)) {
            html(response, 400, projectPage(currentProject, filter, 'Invalid task priority', priorityFilter, dueRange, search));
            return;
          }
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !setTaskPriority.run(priority, id, project.id).changes) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        } else {
          const id = Number(taskId);
          if (!Number.isSafeInteger(id) || !updateTask.run(body.get('completed') === '1' ? 1 : 0, id, project.id).changes) {
            html(response, 404, page('Task not found', '<h1>Task not found</h1>'));
            return;
          }
        }
        redirect(response, `/projects/${project.id}?${taskFilterQuery(filter, priorityFilter, dueRange, search)}`);
      }
    } else {
      html(response, 404, page('Not found', '<h1>Not found</h1>'));
    }
  } catch (error) {
    if (error.status === 413) {
      html(response, 413, page('Request too large', '<h1>Request too large</h1>'));
      return;
    }
    console.error(error);
    if (!response.headersSent) html(response, 500, page('Server error', '<h1>Server error</h1>'));
    else response.end();
  }
});

server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on port ${server.address().port}`));
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let logs = '';
  child.stderr.on('data', chunk => { logs += chunk; });
  const address = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server did not start: ${logs}`));
    }, 10_000);
    child.once('error', error => { clearTimeout(timeout); reject(error); });
    child.once('exit', code => {
      clearTimeout(timeout);
      reject(new Error(`Server exited with ${code}: ${logs}`));
    });
    let output = '';
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/Workboard listening on port (\d+)/);
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    address,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('directory bulk completion intersects filters, protects read-only tasks and persists only completion', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-directory-bulk-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  const snapshot = () => {
    const database = new DatabaseSync(databasePath);
    try {
      return {
        projects: database.prepare('SELECT * FROM projects ORDER BY id').all(),
        tasks: database.prepare('SELECT * FROM tasks ORDER BY id').all().map(row => ({ ...row })),
        positions: database.prepare('SELECT * FROM task_project_positions ORDER BY task_id, project_id').all(),
      };
    } finally { database.close(); }
  };
  try {
    server = await startServer(databasePath);
    const post = (path, fields = {}) => fetch(server.address + path, {
      method: 'POST', body: new URLSearchParams(fields), redirect: 'manual',
    });
    const view = async (path = '/directory') => (await fetch(server.address + path)).text();
    const titles = html => [...html.matchAll(/data-testid="directory-task-title">([^<]*)<\/div>/g)].map(match => match[1]);
    const task = (title, fields = {}) => ({
      title, completed: false, priority: 'High', dueDate: '2024-02-29',
      notes: '  日本語 <b>literal</b>\nlast  ', deleted: false, ...fields,
    });
    const imported = async (name, archived, tasks) => {
      assert.equal((await post('/projects/import', {
        name, json: JSON.stringify({ format: 'workboard-project', version: 1,
          project: { name, archived, defaultPriority: 'Low', tasks } }),
      })).status, 303);
    };
    await imported('First owner', false, [
      task('Alpha\t  FIRST'), task('Alpha first done', { completed: true }),
      task('Alpha first deleted', { deleted: true }),
      task('Alpha first low', { priority: 'Low' }),
      task('Alpha first later', { dueDate: '2024-03-01' }),
      task('Alpha first undated', { dueDate: '' }), task('Other title'),
    ]);
    await imported('Second owner', false, [task('ALPHA first second')]);
    await imported('Archived owner', true, [task('Alpha first archived')]);
    const original = snapshot();
    const query = '?filter=Open&priorityFilter=High&dueFrom=2024-02-29&dueThrough=2024-02-29&search=ALPHA%09++first&scope=Active';
    const selected = await view('/directory' + query);
    assert.deepEqual(titles(selected), ['Alpha\t  FIRST', 'ALPHA first second']);
    assert.match(selected, /<button type="submit">Complete visible tasks<\/button>/);
    assert.match(selected, /<button type="submit" disabled>Reopen visible tasks<\/button>/);
    assert.doesNotMatch(selected, /No matching tasks/);
    const complete = await post('/directory/complete' + query);
    assert.equal(complete.status, 303);
    const location = complete.headers.get('location');
    const params = new URL(location, server.address).searchParams;
    assert.equal(params.get('filter'), 'Open');
    assert.equal(params.get('priorityFilter'), 'High');
    assert.equal(params.get('dueFrom'), '2024-02-29');
    assert.equal(params.get('dueThrough'), '2024-02-29');
    assert.equal(params.get('search'), 'ALPHA\t  first');
    assert.equal(params.get('scope'), 'Active');
    const empty = await view(location);
    assert.deepEqual(titles(empty), []);
    assert.match(empty, /role="status">No matching tasks<\/p>/);
    assert.match(empty, /<button type="submit" disabled>Complete visible tasks/);
    assert.match(empty, /<button type="submit" disabled>Reopen visible tasks/);
    // Native navigation renders resolved results; hide the old announcement on submission.
    assert.match(empty, /document.addEventListener\('submit'/);
    assert.match(empty, /announcement.hidden = true/);
    const expected = {
      ...original,
      tasks: original.tasks.map(task => [1, 8].includes(task.id) ? { ...task, completed: 1 } : task),
    };
    assert.deepEqual(snapshot(), expected);
    const home = await view('/');
    assert.deepEqual([...home.matchAll(/data-testid="project-summary">([^<]*)/g)].map(match => match[1]),
      ['2/6 completed', '1/1 completed']);
    // All matches both completion states: only the still-open matching task is changed.
    const allQuery = query.replace('filter=Open', 'filter=All');
    assert.match(await view('/directory' + allQuery), /<button type="submit" disabled>Complete visible tasks/);
    await post('/directory/complete' + allQuery);
    assert.deepEqual(snapshot(), expected);
    // Disabled actions cannot mutate archived/deleted tasks even via direct requests.
    for (const suffix of ['?scope=Archived', '?filter=Deleted', '?search=absent']) {
      const html = await view('/directory' + suffix);
      for (const label of ['Complete visible tasks', 'Reopen visible tasks']) {
        assert.ok(html.includes(`<button type="submit" disabled>${label}</button>`));
      }
      for (const action of ['complete', 'reopen']) {
        assert.equal((await post('/directory/' + action + suffix)).status, 303);
      }
      assert.deepEqual(snapshot(), expected);
    }
    assert.equal((await post('/directory/reopen?dueFrom=2023-02-29')).status, 400);
    assert.deepEqual(snapshot(), expected);
    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.deepEqual(snapshot(), expected);
    assert.equal(await view(location), empty);
    // Moves and returns retain the bulk-updated state and reserved positions.
    await post('/projects/1/tasks/1/move', { destinationProject: '2' });
    await post('/projects/2/tasks/1/move', { destinationProject: '1' });
    assert.deepEqual(snapshot().tasks, expected.tasks);
    const completedQuery = query.replace('filter=Open', 'filter=Completed');
    assert.deepEqual(titles(await view('/directory' + completedQuery)),
      ['Alpha\t  FIRST', 'Alpha first done', 'ALPHA first second']);
    const reopened = await post('/directory/reopen' + completedQuery);
    const reopenedPage = await view(reopened.headers.get('location'));
