      assert.match(form[0], new RegExp(`id="task-due-date-${taskId}" name="dueDate" type="text" value="${expected}"${disabled ? ' disabled' : ''}>`));
      assert.match(form[0], new RegExp(`<button type="submit"${disabled ? ' disabled' : ''}>Save due date</button>`));
    }
