        }
        redirect(response, `/projects/${project.id}?${taskFilterQuery(filter, priorityFilter, dueRange, search)}`);
      }
    } else {
      html(response, 404, page('Not found', '<h1>Not found</h1>'));
    }
  } catch (error) {
    if (error.status === 413) {
