import os, subprocess, tempfile, time, urllib.request, json, signal
with tempfile.TemporaryDirectory(prefix='workboard-launch-') as directory:
    process = subprocess.Popen(['npm', 'start'], env={**os.environ, 'PORT': '18080', 'DB_PATH': directory + '/workboard.sqlite'}, stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
    try:
        for attempt in range(100):
            try:
                with urllib.request.urlopen('http://127.0.0.1:18080/health', timeout=1) as response:
                    assert response.status == 200
                    assert json.load(response) == {'status': 'ok'}
                break
            except OSError:
                if process.poll() is not None:
                    raise RuntimeError(process.stderr.read().decode())
                time.sleep(.05)
        else:
            raise RuntimeError('Health check timed out')
        print('npm start with PORT and DB_PATH: HTTP 200, {\"status\":\"ok\"}')
    finally:
        os.killpg(process.pid, signal.SIGTERM)
        process.communicate(timeout=10)
